#pragma once

#include <array>
#include "DrumSynth.h"
#include "Pattern.h"
#include "RhythmTypes.h"

namespace rf
{
    // The sequencer + drum mixer. It is used both by the real-time audio callback and by the
    // offline WAV exporter, so exported audio is generated by exactly the same code path.
    // It never allocates, locks or does I/O.
    class RhythmEngine
    {
    public:
        struct Settings
        {
            int   timeSig = 2;
            int   subdiv = 1;
            float swing = 0.0f;               // 0..1
            int   fillEveryBars = 0;          // 0 = no fills
            float levels[numInstruments] = { 0.8f, 0.8f, 0.8f, 0.8f };
            float masterGain = 0.7f;          // linear gain
        };

        // Describes one block of audio in musical time (quarter notes, "ppq").
        struct BlockTiming
        {
            double ppqStart = 0.0;       // musical position of sample 0 of the block
            double ppqPerSample = 0.0;   // tempo expressed per sample
            double trigFrom = 0.0;       // steps with trigFrom <= position < trigTo are triggered
            double trigTo = 0.0;         // (an empty window means: only let existing voices ring out)
        };

        void prepare (double sampleRate) noexcept;
        void reset() noexcept;

        // Renders numSamples of stereo audio (overwrites the buffers).
        void renderBlock (const Pattern& pattern, const Settings& settings, const BlockTiming& timing,
                          float* left, float* right, int numSamples) noexcept;

    private:
        struct Event { int sample; int inst; float velocity; };
        static constexpr int maxEvents = 1024;

        int collectEvents (const Pattern&, const Settings&, const BlockTiming&, int numSamples) noexcept;
        void renderSegment (const Settings&, float* left, float* right, int from, int to) noexcept;

        DrumKit kit;
        std::array<Event, maxEvents> events {};
        float smoothedLevels[numInstruments] = { 0, 0, 0, 0 };
        float smoothedMaster = 0.0f;
        float smoothCoeff = 0.01f;
        float gainL[numInstruments] {}, gainR[numInstruments] {};
        bool  smoothersInitialised = false;
    };
}
